import "server-only";
import { mkdir, readFile, unlink, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";

/**
 * Photo storage. Keys look like "u/<id>.webp" and "u/<id>-sm.webp".
 * Local driver: files on disk under UPLOAD_DIR, served by /media/[...key].
 * Production: replace these three functions with S3 / Cloudflare R2 calls (same keys), and point
 * publicUrl() at the CDN. Nothing else in the app touches the filesystem.
 */
const root = () => resolve(process.cwd(), process.env.UPLOAD_DIR ?? "../.uploads");

/** Keys are generated by us, but validate anyway so a crafted key can never escape the folder. */
export const KEY_PATTERN = /^u\/[a-z0-9]{10,40}(-sm)?\.webp$/;

function pathFor(key: string) {
  if (!KEY_PATTERN.test(key)) throw new Error(`Invalid storage key: ${key}`);
  return join(root(), key);
}

export async function putObject(key: string, data: Buffer) {
  const p = pathFor(key);
  await mkdir(dirname(p), { recursive: true });
  await writeFile(p, data);
}

export async function getObject(key: string): Promise<Buffer | null> {
  try {
    return await readFile(pathFor(key));
  } catch {
    return null;
  }
}

export async function deleteObject(key: string) {
  await unlink(pathFor(key)).catch(() => {});
}

export function publicUrl(key: string) {
  return `/media/${key}`;
}

/** Card-sized variant of a stored photo URL; seeded/legacy URLs are returned as-is. */
export function smallVariant(url: string) {
  return url.startsWith("/media/u/") && !url.endsWith("-sm.webp") ? url.replace(/\.webp$/, "-sm.webp") : url;
}
